import test from "node:test";
import assert from "node:assert/strict";
import { SharedEngine } from "./engine-share.js";

/** An in-memory Web Locks: exclusive, FIFO, ifAvailable — the semantics SharedEngine relies on. */
function fakeLocks() {
  const held = new Map(), queue = new Map();
  const grantNext = (name) => {
    const q = queue.get(name) ?? [];
    if (held.get(name) || !q.length) return;
    const { cb, resolve, reject } = q.shift();
    held.set(name, true);
    Promise.resolve(cb({ name })).then(resolve, reject).finally(() => { held.delete(name); grantNext(name); });
  };
  return {
    request(name, opts, cb) {
      if (typeof opts === "function") { cb = opts; opts = {}; }
      return new Promise((resolve, reject) => {
        if (opts.ifAvailable && held.get(name)) return Promise.resolve(cb(null)).then(resolve, reject);
        (queue.get(name) ?? queue.set(name, []).get(name)).push({ cb, resolve, reject });
        grantNext(name);
      });
    },
    heldNow: (n) => !!held.get(n),
  };
}
/** BroadcastChannel hub: a message reaches every OTHER channel of the same name, asynchronously. */
function fakeHub() {
  const chans = [];
  return (name) => {
    const c = { name, onmessage: null, closed: false, postMessage(data) { for (const o of chans) if (o !== c && o.name === name && !o.closed) queueMicrotask(() => o.onmessage?.({ data: structuredClone(data) })); }, close() { c.closed = true; } };
    chans.push(c);
    return c;
  };
}
/** A stand-in for WorkerEngine: counts how many times a "model" was really loaded. */
function fakeEngineFactory(stats, { failLoad = false } = {}) {
  return (onProgress) => {
    stats.built++;
    const e = {
      loaded: false, modelId: null, pending: 0, contextWindow: 4096, engine: null,
      async load(id) { if (failLoad) throw new Error("no WebGPU"); stats.loads++; onProgress({ progress: 0.5 }); e.modelId = id; e.loaded = true; e.engine = { unload: async () => {} }; },
