const tick = (ms = 20) => new Promise((r) => setTimeout(r, ms));

test("three tabs open: ONE engine is built and ONE model loaded; the others proxy", async () => {
  const locks = fakeLocks(), hub = fakeHub(), stats = { built: 0, loads: 0 };
  const a = tab(locks, hub, stats), b = tab(locks, hub, stats), c = tab(locks, hub, stats);
  await a.load("gemma-2-2b");
